You are given an array of integers. Write a function that returns the sum of the elements at the even indices.
*/

int sumEvenIndices(int[] arr)
{
    int sum = 0;
    foreach (int i, int val; arr)
    {
        if (i % 2 == 0)
        {
            sum += val;
        }
    }
    return sum;
}
